export interface PerformanceMetrics {
  durationMs: number;
  averageFps: number;
  droppedFrames: number;
  longTasks: number;
  longTaskDurationMs: number;
}

/**
 * Standard double requestAnimationFrame promise to ensure DOM painting and layout completion.
 */
export function waitForDoubleRaf(): Promise<void> {
  return new Promise<void>((resolve) =>
    requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
  );
}

export interface BenchmarkInteractionOptions {
  containerSelector: string;
  sizeEventName: string;
  datasetSize: number;
  interactionWindowMs: number;
  beforeStart?: (waitFrame: () => Promise<void>) => Promise<void> | void;
  tick?: (actionIndex: number, waitFrame: () => Promise<void>) => Promise<void> | void;
}

export interface BenchmarkInteractionResult {
  datasetSize: number;
  durationMs: number;
  averageFps: number;
  averageFrameMs: number;
  droppedFrames: number;
  longTasks: number;
  longTaskDurationMs: number;
  peakHeapMb?: number;
}

/**
 * Tracks browser rendering health by sampling animation frame timing and observing
 * long task entries while a UI interaction is running.
 */
export class PerformanceTracker {
  private animationFrameId = 0;
  private frameTimestamps: number[] = [];
  private performanceObserver?: PerformanceObserver;
  private longTaskCount = 0;
  private totalLongTaskDurationMs = 0;
  private monitoringStartedAt = 0;

  /**
   * Starts collecting frame and long-task performance data for the current run.
   */
  startMonitoring(): void {
    this.cancelAnimationFrameLoop();
    this.frameTimestamps = [];
    this.longTaskCount = 0;
    this.totalLongTaskDurationMs = 0;
    this.monitoringStartedAt = performance.now();

    const supportedEntryTypes = PerformanceObserver.supportedEntryTypes;
    const observedTypes = ['longtask', 'long-animation-frame'].filter((type) => supportedEntryTypes.includes(type));

    if (observedTypes.length > 0) {
      this.performanceObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.duration > 50) {
            this.longTaskCount += 1;
            this.totalLongTaskDurationMs += entry.duration;
          }
        }
      });
      this.performanceObserver.observe({ entryTypes: observedTypes });
    }

    const sampleFrame = (timestamp: number): void => {
      this.frameTimestamps.push(timestamp);
      this.animationFrameId = requestAnimationFrame(sampleFrame);
    };

    this.animationFrameId = requestAnimationFrame(sampleFrame);
  }

  /**
   * Stops monitoring and returns a summary of the measured performance metrics.
   */
  stopMonitoring(): PerformanceMetrics {
    const durationMs = Math.max(performance.now() - this.monitoringStartedAt, 1);
    this.cancelAnimationFrameLoop();
    this.performanceObserver?.disconnect();
    this.performanceObserver = undefined;

    let droppedFrames = 0;
    for (let index = 1; index < this.frameTimestamps.length; index += 1) {
      const interval = this.frameTimestamps[index] - this.frameTimestamps[index - 1];
      if (interval > 33.3) {
        droppedFrames += Math.max(1, Math.round(interval / 16.67) - 1);
      }
    }

    return {
      durationMs,
      averageFps: this.frameTimestamps.length / (durationMs / 1000),
      droppedFrames,
      longTasks: this.longTaskCount,
      longTaskDurationMs: this.totalLongTaskDurationMs,
    };
  }

  /**
   * Alias for startMonitoring for compatibility with performance test runner.
   */
  start(): void {
    this.startMonitoring();
  }

  /**
   * Alias for stopMonitoring for compatibility with performance test runner.
   */
  stop(): PerformanceMetrics {
    return this.stopMonitoring();
  }

  /**
   * Executes a standardized performance interaction loop in the browser.
   * Handles container event dispatch, readiness awaiting, tracker lifecycle,
   * frame timing, and peak heap sampling.
   */
  async runInteraction(options: BenchmarkInteractionOptions): Promise<BenchmarkInteractionResult> {
    const {
      containerSelector,
      sizeEventName,
      datasetSize,
      interactionWindowMs,
      beforeStart,
      tick,
    } = options;

    const waitFrame = () => waitForDoubleRaf();

    // Reset container readiness
    document.querySelector(containerSelector)?.removeAttribute('data-ready');

    // Dispatch size event
    window.dispatchEvent(new CustomEvent(sizeEventName, { detail: { size: datasetSize } }));

    // Wait for container readiness
    await new Promise<void>((resolve) => {
      const check = () => {
        const el = document.querySelector(`${containerSelector}[data-ready="true"]`);
        if (el) {
          resolve();
          return;
        }
        requestAnimationFrame(check);
      };
      check();
    });
    await waitFrame();

    // Run optional verification before starting benchmark metrics collection
    if (beforeStart) {
      await beforeStart(waitFrame);
    }

    const endAt = performance.now() + interactionWindowMs;
    let actionIndex = 0;

    this.start();

    let peakHeapBytes =
      (performance as unknown as { memory?: { usedJSHeapSize?: number } }).memory
        ?.usedJSHeapSize ?? 0;

    while (performance.now() < endAt) {
      if (tick) {
        await tick(actionIndex, waitFrame);
      }
      await waitFrame();
      const currentHeap =
        (performance as unknown as { memory?: { usedJSHeapSize?: number } }).memory
          ?.usedJSHeapSize ?? 0;
      if (currentHeap > peakHeapBytes) {
        peakHeapBytes = currentHeap;
      }
      actionIndex += 1;
    }

    const metrics = this.stop();
    return {
      datasetSize,
      durationMs: metrics.durationMs,
      averageFps: metrics.averageFps,
      averageFrameMs: 1000 / Math.max(metrics.averageFps, 0.001),
      droppedFrames: metrics.droppedFrames,
      longTasks: metrics.longTasks,
      longTaskDurationMs: metrics.longTaskDurationMs,
      peakHeapMb:
        peakHeapBytes > 0
          ? Number((peakHeapBytes / (1024 * 1024)).toFixed(2))
          : undefined,
    };
  }

  /**
   * Cancels the animation frame loop used for sampling frame timing.
   */
  private cancelAnimationFrameLoop(): void {
    if (this.animationFrameId !== 0) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = 0;
    }
  }
}

/**
 * Creates a fresh performance tracker instance for monitoring Storybook interactions.
 */
export function createPerformanceTracker(): PerformanceTracker {
  return new PerformanceTracker();
}

declare global {
  interface Window {
    __storybookPerformanceTracker?: PerformanceTracker;
    __storybookPerfTracker?: PerformanceTracker;
  }
}

if (typeof window !== 'undefined') {
  const tracker = createPerformanceTracker();
  window.__storybookPerformanceTracker = tracker;
  window.__storybookPerfTracker = tracker;
}

