      check();
    });
    await waitFrame();

    // Run optional verification before starting benchmark metrics collection
    if (beforeStart) {
      await beforeStart(waitFrame);
    }

    const endAt = performance.now() + interactionWindowMs;
    let actionIndex = 0;

    this.start();

    let peakHeapBytes =
      (performance as unknown as { memory?: { usedJSHeapSize?: number } }).memory
        ?.usedJSHeapSize ?? 0;

    while (performance.now() < endAt) {
      if (tick) {
        await tick(actionIndex, waitFrame);
      }
      await waitFrame();
      const currentHeap =
        (performance as unknown as { memory?: { usedJSHeapSize?: number } }).memory
          ?.usedJSHeapSize ?? 0;
      if (currentHeap > peakHeapBytes) {
        peakHeapBytes = currentHeap;
      }
      actionIndex += 1;
    }

    const metrics = this.stop();
    return {
      datasetSize,
      durationMs: metrics.durationMs,
      averageFps: metrics.averageFps,
      averageFrameMs: 1000 / Math.max(metrics.averageFps, 0.001),
      droppedFrames: metrics.droppedFrames,
      longTasks: metrics.longTasks,
      longTaskDurationMs: metrics.longTaskDurationMs,
      peakHeapMb:
        peakHeapBytes > 0
          ? Number((peakHeapBytes / (1024 * 1024)).toFixed(2))
          : undefined,
    };
  }

  /**
   * Cancels the animation frame loop used for sampling frame timing.
   */
  private cancelAnimationFrameLoop(): void {
    if (this.animationFrameId !== 0) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = 0;
    }
  }
}

/**
 * Creates a fresh performance tracker instance for monitoring Storybook interactions.
 */
export function createPerformanceTracker(): PerformanceTracker {
  return new PerformanceTracker();
}

declare global {
  interface Window {
    __storybookPerformanceTracker?: PerformanceTracker;
    __storybookPerfTracker?: PerformanceTracker;
  }
}

if (typeof window !== 'undefined') {
  const tracker = createPerformanceTracker();
  window.__storybookPerformanceTracker = tracker;
  window.__storybookPerfTracker = tracker;
}

